{
  "name": "Juniper",
  "version": 1,
  "color": {
    "themes": [
      { "id": "light", "name": "Light" },
      { "id": "dark", "name": "Dark" }
    ],
    "tokens": [
      { "name": "surface", "value": { "light": "#f7f2e8", "dark": "#171511" }, "usage": "Cream. The page, in the app, on the site and on the bag." },
      { "name": "surface-raised", "value": { "light": "#fffdf8", "dark": "#211e18" }, "usage": "Cards, fields, sheets and menus: anything that sits on the page." },
      { "name": "surface-sunken", "value": { "light": "#e7e2d6", "dark": "#0f0e0b" }, "usage": "Fog. Wells, the track of a segmented control, the tab bar." },

      { "name": "ink", "value": { "light": "#1d1b16", "dark": "#f3eee2" }, "usage": "Headings and body copy, on every surface." },
      { "name": "ink-muted", "value": { "light": "#5a5448", "dark": "#b3ab9b" }, "usage": "Secondary copy, hints and metadata, on every surface." },

      { "name": "line", "value": { "light": "#d6cfbf", "dark": "#38342b" }, "usage": "Hairlines between rows and around cards. Decoration only." },
      { "name": "line-strong", "value": { "light": "#8a8272", "dark": "#7d7566" }, "usage": "Borders that mark a control: fields, the secondary button. 3:1 on every surface." },

      { "name": "accent", "value": { "light": "#a8563a", "dark": "#d08c70" }, "usage": "Clay, a calmer terracotta. The one action a view is for, and where you are: the primary button, the tab." },
      { "name": "accent-strong", "value": { "light": "#863f22", "dark": "#e5a990" }, "usage": "Clay as text, and the primary button when pressed. Reads on every surface and on accent-soft." },
      { "name": "accent-soft", "value": { "light": "#f1ddd3", "dark": "#38231b" }, "usage": "A wash behind accent-strong text: the New tag, a selected row." },
      { "name": "accent-focus", "value": "{accent}", "usage": "The focus ring: 2px solid, 2px away from the control. An alias, so it moves with accent." },

      { "name": "on-accent", "value": { "light": "#ffffff", "dark": "#1d1b16" }, "usage": "Labels and icons on an accent fill." },
      { "name": "on-forest", "value": { "light": "#f7f2e8", "dark": "#f3eee2" }, "usage": "Copy on a forest fill: toasts, the bag label." },
      { "name": "on-honey", "value": "#1d1b16", "usage": "Copy on a honey fill. Always ink, in both themes." },

      { "name": "forest", "value": { "light": "#20402f", "dark": "#2f5d45" }, "usage": "The brand's deep green. Fills that carry copy: toasts, the bag label, a switch that is on." },
      { "name": "forest-soft", "value": { "light": "#dbe5da", "dark": "#1c2d24" }, "usage": "A wash behind text-success: the In stock tag." },

      { "name": "moss", "value": { "light": "#5b7f5e", "dark": "#8fb392" }, "usage": "Marks that say fine: the roast meter, a check, the sprig. Never body copy in the light theme." },
      { "name": "moss-soft", "value": { "light": "#dfe8d8", "dark": "#232f24" }, "usage": "The empty dots of the roast meter and other quiet tracks." },
      { "name": "honey", "value": { "light": "#e3a53c", "dark": "#e9b452" }, "usage": "First Light's own color. Seasonal highlights and the Limited tag, a little at a time." },
      { "name": "honey-soft", "value": { "light": "#f8e9c6", "dark": "#3a2e14" }, "usage": "A wash behind ink copy for seasonal notes." },

      { "name": "danger", "value": { "light": "#a4262c", "dark": "#f08a80" }, "usage": "Errors and actions that cannot be undone. Deeper than accent, so the two differ in lightness, and always with words." },
      { "name": "danger-soft", "value": { "light": "#f6dcd9", "dark": "#3d1a17" }, "usage": "A wash behind text-danger: the Paused tag." },

      { "name": "text-link", "value": "{accent-strong}", "usage": "Links in running copy, underlined. Follows accent-strong." },
      { "name": "text-success", "value": { "light": "{forest}", "dark": "{moss}" }, "usage": "Good news in words: In stock, Delivered." },
      { "name": "text-danger", "value": "{danger}", "usage": "An error message under a field. Follows danger." }
    ]
  },
  "type": {
    "fonts": [],
    "families": {
      "display": "'Iowan Old Style', 'Palatino Linotype', Georgia, serif",
      "sans": "system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif",
      "mono": "ui-monospace, 'SF Mono', Menlo, Consolas, monospace"
    },
    "groups": [
      {
        "name": "Display",
        "family": "display",
        "note": "The serif says things: names and headlines, always at regular weight, so size alone sets the order. No web font: the stack falls back to faces every reader already has.",
        "styles": [
          { "name": "display", "fontSize": "56px", "lineHeight": "60px", "fontWeight": 400, "letterSpacing": "-0.02em", "sample": "First Light is here", "usage": "One per page or screen: a launch headline, the cover." },
          { "name": "headline", "fontSize": "36px", "lineHeight": "42px", "fontWeight": 400, "letterSpacing": "-0.015em", "sample": "Roasted Thursday, at your door by Saturday", "usage": "Section openers and screen titles." },
          { "name": "title", "fontSize": "24px", "lineHeight": "30px", "fontWeight": 400, "letterSpacing": "-0.01em", "sample": "Hearth, our dark roast", "usage": "Card titles and the name of a coffee." }
        ]
      },
      {
        "name": "Text",
        "family": "sans",
        "note": "The system sans does things: copy, labels and controls.",
        "styles": [
          { "name": "body-lg", "fontSize": "18px", "lineHeight": "28px", "fontWeight": 400, "sample": "Apricot, jasmine and a little honey. A light roast for slow mornings.", "usage": "Lead paragraphs and the description of a coffee." },
          { "name": "body", "fontSize": "16px", "lineHeight": "24px", "fontWeight": 400, "sample": "We roast every Thursday and ship the same day, so the bag you open is days old, not months.", "usage": "Running copy and field values." },
          { "name": "label", "fontSize": "14px", "lineHeight": "20px", "fontWeight": 600, "sample": "Start a subscription", "usage": "Buttons, tabs, field labels. Sentence case, verb first." },
          { "name": "caption", "fontSize": "13px", "lineHeight": "18px", "fontWeight": 400, "sample": "Change or skip a delivery until Wednesday noon.", "usage": "Hints, metadata and the small print under a field." },
          { "name": "overline", "fontSize": "12px", "lineHeight": "16px", "fontWeight": 600, "letterSpacing": "0.08em", "textTransform": "uppercase", "sample": "Spring blend · Light roast", "usage": "A short line above a title. The only uppercase in the system." }
        ]
      },
      {
        "name": "Data",
        "family": "mono",
        "note": "Numbers that line up: prices, weights and dates in lists.",
        "styles": [
          { "name": "data", "fontSize": "14px", "lineHeight": "20px", "fontWeight": 500, "sample": "$18.00 · 250 g · Apr 17", "usage": "Prices, weights and order numbers, wherever digits should align." }
        ]
      }
    ]
  },
  "spacing": {
    "note": "A 4px base. Inside a component use space-1 to space-4; between components space-5 and up.",
    "tokens": [
      { "name": "space-1", "value": "4px", "usage": "Between an icon and its label." },
      { "name": "space-2", "value": "8px", "usage": "Between a field and its hint; the gap in a row of tags." },
      { "name": "space-3", "value": "12px", "usage": "A button's vertical padding; rows in a list." },
      { "name": "space-4", "value": "16px", "usage": "Card padding on a phone; the page gutter." },
      { "name": "space-5", "value": "24px", "usage": "Card padding on wider screens; between cards." },
      { "name": "space-6", "value": "32px", "usage": "Between the groups of a form." },
      { "name": "space-7", "value": "48px", "usage": "Between sections of a page." },
      { "name": "space-8", "value": "72px", "usage": "Above a display headline." }
    ]
  },
  "radius": {
    "note": "Soft, never bubbly. The smaller the thing, the smaller its corner.",
    "tokens": [
      { "name": "radius-sm", "value": "6px", "usage": "Tags, the thumb of a segmented control." },
      { "name": "radius-md", "value": "10px", "usage": "Buttons, fields, toasts." },
      { "name": "radius-lg", "value": "16px", "usage": "Cards, sheets and the blocks on the cover." },
      { "name": "radius-pill", "value": "999px", "usage": "Switches and the roast meter's dots. Nothing else is fully round." }
    ]
  },
  "shadow": {
    "note": "Borders before shadows: a card gets a line, and a shadow only once it floats above the page.",
    "tokens": [
      { "name": "shadow-sm", "value": { "light": "0 1px 2px rgba(29, 27, 22, 0.08)", "dark": "0 1px 2px rgba(0, 0, 0, 0.5)" }, "usage": "The thumb of a switch or a segmented control." },
      { "name": "shadow-md", "value": { "light": "0 6px 16px -4px rgba(29, 27, 22, 0.14), 0 2px 4px rgba(29, 27, 22, 0.06)", "dark": "0 6px 16px -4px rgba(0, 0, 0, 0.6), 0 2px 4px rgba(0, 0, 0, 0.4)" }, "usage": "Menus and a card that is being dragged." },
      { "name": "shadow-lg", "value": { "light": "0 18px 40px -12px rgba(29, 27, 22, 0.22), 0 4px 10px rgba(29, 27, 22, 0.08)", "dark": "0 18px 40px -12px rgba(0, 0, 0, 0.7), 0 4px 10px rgba(0, 0, 0, 0.5)" }, "usage": "Toasts and sheets: what floats over everything else." }
    ]
  },
  "motion": {
    "note": "Things settle; nothing bounces. Wrap every transition in prefers-reduced-motion.",
    "tokens": [
      { "name": "duration-fast", "value": "120ms", "usage": "Hover and press states." },
      { "name": "duration-base", "value": "200ms", "usage": "A switch, a tab underline, a toast arriving." },
      { "name": "duration-slow", "value": "320ms", "usage": "Sheets and anything that crosses the screen." },
      { "name": "ease-settle", "value": "cubic-bezier(0.2, 0.8, 0.2, 1)", "usage": "The default curve: quick out, slow to rest." }
    ]
  }
}

