files.project/components/Notice/Notice.d.ts:
export interface NoticeProps {
  /**
   * Seasonal is for launches; plain for everything else.
   * @default "plain"
   */
  tone?: 'plain' | 'seasonal';
  /** A few words, sentence case, no period. */
  title: string;
  /** One sentence under the title. */
  children: string;
  /** Somewhere to go. One link at most. */
  link?: { label: string; href: string };
}
